local Text_AwakerTalent = readonly({
  AwakerTalent_117311_TalentDesc_1 = {
    Text = "Pollux’un bir turda oynadığı ilk Komut Kartı, SLD’sinin %200’ü kadar ek Hasar verir, DEF’inin %50’si kadar ek Kalkan üretir ve +10 Aliemus kazandırır.\nSavaştan sonra, keşif sırasında Pollux’un Temel Hasarı ve \"Izdırapla Kefaret\" Hasar etkisi %20 artırılır ve Reis Savaşı’nda \"Izdırapla Kefaret\" Hasar etkisi ikiye katlanır."
  },
  AwakerTalent_117311_TalentName_1 = {
    Text = "Izdırapla Kefaret"
  },
  AwakerTalent_120347_TalentDesc_1 = {
    Text = "Bu karakter takımda olduğunda, Derin Deniz Diyarı \"Benthos: Aequor\" Diyarına dönüşür.\n\nTemel Dokunaç Hasarı, takımın Maksimum can'ının %5'i olarak değiştirilir.\n\nKeşif başladıktan sonra Takım Hasar Güçlendirmesi +%50 (Takım tamamen Aequor ve Kaos Uyandırıcılardan oluşuyorsa etki iki katına çıkar, ancak ek başlangıç Dokunaçları elde edilmez).\nDokunaç Toplanması etkisi kaldırılır.\nDokunaç Duruşu \"Benthos: Dokunaç Duruşu\" olarak değişir.\n\n\"Benthos: Sakin Deniz\": Anında Maksimum can'ın %25'i kadar Kalkan oluşturur ve Dokunaçlar tur sonunda artık saldırmaz; 3 tur bekleme süresi.\n\"Benthos: Azgın Dalgalar\": O tur için Dokunaç Hasarı × %125; Aktif Hasar verdikten sonra 1 Dokunaç saldırır; tur sonunda 1 Dokunaç kaybedilir; 3 tur bekleme süresi.\nDiyar Ustalığı \"Benthos: Aequor Ustalığı\" olarak sayılır. Her puan şunları sağlar: Sakin Deniz Duruşu'nun Kalkan Üretimi +%0,025 Maksimum can. Azgın Dalgalar Duruşu'nun Dokunaç Hasarı +%0,025.\nTakım tamamen Aequor ve Kaos Uyandırıcılardan oluşuyorsa \"Benthos: Diyar Ustalığı\" etkisi iki katına çıkar."
  },
  AwakerTalent_120347_TalentName_1 = {
    Text = "Işıksız Dip"
  },
  AwakerTalent_122481_TalentDesc_1 = {
    Text = "Bu yetenek yalnızca \"Yıldız Bölümü\" aşamalarında etkilidir.\nBu Uyanan’ın CAN, Saldırı ve Savunması [Arg1]% artar ve ilk Uyanışlarında [Arg2] Anahtar Alevi kazanırlar.\nMouchette’in \"Rüya Hükümdarı\" düşmanlara karşı Final Hasarı +[Arg5]%. Tüm Uyananların \"Darbe\" Temel Hasarı +[Arg3]%. Ölüm Direnci tetiklendikten sonra, Mouchette [Arg4] Aliemus kazanır."
  },
