  AwakerTalent_122607_TalentDesc_1 = {
    Text = "Her 2 \"Darbe\" kartı oynandığında, Mouchette bir Av gerçekleştirir; rastgele, Mouchette’in Saldırı gücünün %30’una eşit 1 adet Hasar verir (bu, \"Darbe\" olarak sayılır). Bu Etki tur başına en fazla 4 kez tetiklenebilir."
  },
  AwakerTalent_122607_TalentName_1 = {
    Text = "Dramatik Karşılaşma"
  },
  AwakerTalent_125362_TalentDesc_1 = {
    Text = "Bu yetenek yalnızca \"Yıldız Saltanatı\" aşamalarında etkilidir.\nBu Uyandırıcının KON, SLD ve SAV değerleri +[Arg1]% artar ve ilk Uyanışında [Arg2] S-Enerjisi kazanır.\nTüm Uyandırıcıların Zehir Tetikleme etkisi +[Arg3]% artar. \n\"Büyülenmiş\" durumunun her yığını, \"İnsansı\" düşmanların verdiği hasarı ek olarak %1 azaltır ve \"Büyülenmiş\" kaldırıldığında, her yığın \"İnsansı\" düşmanlara hedefin Maksimum canının %1'i kadar Sabit Hasar verir."
  },
  AwakerTalent_125362_TalentDesc_10 = {
