  AwakerTalent_127223_TalentDesc_1 = {
    Text = "Arachne takımda olduğunda, Ultra Diyar Tekillik: Ultra olarak yeniden örülür.\nBoyut Mekiği: Her turda ilk Komut Kartı oynanıldıktan sonra, kartın Yanılsama niteliğinde bir Temel Kopyası Ultra Uzay'a yerleştirilir ve 25 yığın Tekillik Feneri kazanır. Bu, Ultra Turlarda tetiklenemez. Bir kart Boyut Mekiği'ni tetiklerse, Tekillik Feneri efektlerinden de yararlanır.\nTekillik Feneri: Her yığın için bir kartın Final Hasar, Sabit Güç & Dokunaç Hasarı kazanımı, Sabit Zehir & Karşı Atak değerleri her biri +%2; Final Kalkan, HP Yenilenmesi ve Güç Azalması her biri +%1 artar. Bu efekt kart oynanıldığında temizlenir. Bu efekte sahip kartlar Boyut Mekiği'ni tetikleyemez.\nUltra Uzay: Dolduğunda, Ultra Tur başlatmak turu sona erdirmez ve yeni bir tur başlatmaz; Sakla özelliği olmayan tüm kartlar atılır, Yanılsama efektleri çözümlenir, Ultra Uzay'daki tüm kartlar çekilir ve Arithmetica 5'e ayarlanır. Mevcut tur Ultra Tur olarak devam eder.\nTekillik Yok Oluşu: Ultra Uzay'daki en soldaki kartı ele çeker. 3 tur bekleme süresi.\nAraştırmanın başında +%50 Hasar Güçlendirmesi ve 15 yığın Tekillik Prizması kazanılır.\nTekillik Prizması: Tüm Komut Kartlarının efektleri, bu kadar yığın Tekillik Feneri'ne sahipmiş gibi artar.\nUltra Ustalık: Her 1 Diyar Ustalığı puanı için, Tekillik Prizması ve Boyut Mekiği'nden gelen Tekillik Feneri yığınları %0,05 artar.\nSaf Hiperboyut: Takım yalnızca Ultra veya Kaos Uyandırıcılarından oluşuyorsa, Ultra Ustalık efekti ve Diyar Hasar Güçlendirmesi iki katına çıkar."
  },
