  AwakerTalent_130398_TalentDesc_1 = {
    Text = "Bu yetenek yalnızca \"Yıldız Hükümranlığı\" aşamalarında geçerlidir.\nBu Uyandırıcı'nın KON, SLD ve SAV değerleri +[Arg1]% artar ve ilk Uyanış'ta [Arg2] S-Enerjisi kazanır.\n\"Saya'nın Şarkısı\" tarafından seçilen Uyandırıcı [Arg3] yığın \"Yayılma Şenliği\" kazanır ve bir sonraki Müfreze 2 kez etkinleşir.\nSaya, \"Caro\" düşmanlara +[Arg4]% Aşınma yığını uygular."
  },
