  AwakerTalent_131854_TalentDesc_1 = {
    Text = "Saya takımda olduğunda, Caro Diyarı Yetiştirme·et'e dönüşür.\n\nEmbriyo Füzyonu: Tur başına kazanılan Embriyo Füzyonu, kaybedilen Can'a bağlı olarak 50~100'e yükselir. Embriyo Füzyonu sınırı 100'den 200'e çıkar. Sınıra ulaşıldığında ele 1 \"Propagül Embriyosu\" eklenir.\n\nPropagül Embriyosu: Bu kartı oynamak artık Kritik Oranı sağlamaz. Yutma artık Kalkan veya Geçici GÜÇ sağlamaz. Her Uyandırıcı her tur ilk kez \"Propagül Embriyosu\" tükettiğinde, 40 yığın \"Yayılma Şenliği\" kazanır: Her yığın, o Uyandırıcının bu turdaki bir sonraki Taşkınlığının aşağıdaki Final efektlerini %1 güçlendirir: Final Hasar, Sabit Kalkan, Sabit HP Yenilenmesi, Sabit Güç/Güç Azalması, Dokunaç HSR Bonusu, Sabit Zehir ve Sabit Karşı Saldırı.\n\nKızıl Ocak: Tur başındaki otomatik birikim, kaybedilen Can'ın %10'una, maksimum Maksimum can'ın %50'sine kadar değişir. Savaş sonunda artık birikmez. 3 tur bekleme süresi.\n\nKızıl Erozyon: Kızıl Ocak kullanıldıktan sonra tüm düşmanlara, onların Maksimum can'larının %1'i kadar Aşınma uygular. Tüketilen Kızıl Ocak ne kadar fazlaysa Aşınma efekti o kadar güçlü olur, maksimum +%100. \"Boş Kabuk\" düşmanlara karşı 5× Aşınma efekti uygular.\n\nKeşif başlangıcında, Maksimum can +%10, takım Hasar Güçlendirmesi +%50 ve tüm Uyandırıcılar Tur başında 20 yığın \"Yayılma Şenliği\" kazanır. Takım yalnızca Caro veya Kaos Uyandırıcılarından oluşuyorsa, bu efektten gelen Hasar Güçlendirmesi iki katına çıkar.\nDiyar Ustalığı \"Yetiştirme·et Ustalığı\"na dönüşür: Her bir Diyar Ustalığı puanı, \"Yetiştirme·et\"ten kazanılan \"Yayılma Şenliği\" yığınlarını %0,05 artırır.\n\nTakım yalnızca Caro veya Kaos Uyandırıcılarından oluşuyorsa, \"Yetiştirme·et Ustalığı\" efekti iki katına çıkar."
  },
