  AwakerTalent_141303_TalentDesc_1 = {
    Text = "Bu Yetenek yalnızca \"Yıldız Hükümranlığı\" Sahnelerinde etkilidir.\nBu Uyandırıcı'nın KON, ATK ve Savunması [Arg1]% artar ve ilk Uyanış kartını oynadıktan sonra [Arg2] S-Enerjisi kazanır.\nPontos'un \"Coşkunun Akrabaları\"na verdiği Sabit Hasar [Arg3]% artar.\n\"Amansız Av\", tüketilen her 10 Aliemus için SLD'nin [Arg4]%'sine eşit Dokunaç Hasarı kazanır. \"Gaunt Tahribatı\" Hasar verdiğinde, aynı zamanda hedefin GÜÇ'ünü geçici olarak SAV'ın [Arg5]%'sine eşit bir miktarda azaltır."
  },
