    Text = "·Bu Yetenek yalnızca \"Yıldız Hükümranlığı\" Sahnelerinde geçerlidir.\n·Bu Uyandırıcının KON, Saldırı ve SAV değerleri [Arg1]% artar ve bu Uyandırıcı ilk kez Uyanış oynadıktan sonra [Arg2] S-Enerjisi kazanır.\n·\"Sınır Kesen Kılıç\" ek olarak [Arg3]% Güç Bonusu kazanır. Bir düşmanı öldürdükten sonra [Arg4] Kara Mühür kazanılır; bu, Lotan: Cetarchon'un Mühür Hasadı Bonusundan yararlanır. Savaş başına en fazla bir kez geçerlidir."
