  AwakerTalent_145718_TalentDesc_1 = {
    Text = "Caraboo takımda olduğunda, Caro Diyarı Yetiştirme·et'e dönüşür.\n\nEmbriyo Füzyonu: Tur başına kazanılan Embriyo Füzyonu, kaybedilen Can'a bağlı olarak 50~100'e yükselir. Embriyo Füzyonu sınırı 100'den 200'e çıkar. Sınıra ulaşıldığında ele 1 \"Propagül Embriyosu\" eklenir.\n\nPropagül Embriyosu: Bu kartı oynamak artık Kritik Oranı sağlamaz. Yutma artık Kalkan veya Geçici GÜÇ sağlamaz. Her Uyandırıcı her tur ilk kez \"Propagül Embriyosu\" tükettiğinde, 40 yığın \"Yayılma Şenliği\" kazanır: Her yığın, o Uyandırıcının bu turdaki bir sonraki Taşkınlığının aşağıdaki Final efektlerini %1 güçlendirir: Final Hasar, Sabit Kalkan, Sabit HP Yenilenmesi, Sabit Güç/Güç Azalması, Dokunaç HSR Bonusu, Sabit Zehir ve Sabit Karşı Saldırı.\n\nKızıl Ocak: Tur başındaki otomatik birikim, kaybedilen Can'ın %10'una, maksimum Maksimum can'ın %50'sine kadar değişir. Savaş sonunda artık birikmez. 3 tur bekleme süresi.\n\nKızıl Erozyon: Kızıl Ocak kullanıldıktan sonra tüm düşmanlara, onların Maksimum can'larının %1'i kadar Aşınma uygular. Tüketilen Kızıl Ocak ne kadar fazlaysa Aşınma efekti o kadar güçlü olur, maksimum +%100. \"Boş Kabuk\" düşmanlara karşı 5× Aşınma efekti uygular.\n\nKeşif başlangıcında, Maksimum can +%10, takım Hasar Güçlendirmesi +%50 ve tüm Uyandırıcılar Tur başında 20 yığın \"Yayılma Şenliği\" kazanır. Takım yalnızca Caro veya Kaos Uyandırıcılarından oluşuyorsa, bu efektten gelen Hasar Güçlendirmesi iki katına çıkar.\nDiyar Ustalığı \"Yetiştirme·et Ustalığı\"na dönüşür: Her bir Diyar Ustalığı puanı, \"Yetiştirme·et\"ten kazanılan \"Yayılma Şenliği\" yığınlarını %0,05 artırır.\n\nTakım yalnızca Caro veya Kaos Uyandırıcılarından oluşuyorsa, \"Yetiştirme·et Ustalığı\" efekti iki katına çıkar."
  },
  AwakerTalent_145718_TalentName_1 = {
    Text = "Yetiştirme·et"
  },
  AwakerTalent_146937_TalentDesc_1 = {
    Text = "Lotan: Cetarchon takımda olduğunda, Kaos Diyarı İlkçağ: Kaos olarak yeniden şekillenir.\n\nİlksel Akış: Temel Keyflare 2000'e yükseltilir, Takım Hasar Güçlendirmesi %50 artırılır ve tüm Uyandırıcıların SLD ve SAV değerleri %10 artırılır. Takım yalnızca Kaos Uyandırıcılarından oluşuyorsa, bu efektten gelen Hasar Güçlendirmesi bonusu iki katına çıkar. Savaşın başında 2000 Keyflare kazanılır.\n\nBirleşen Anahtarlar: Tüm Uyandırıcıların Keyflare Yenilenme Seviyeleri takım ortalamasına ayarlanır. Uyandırıcılar artık tüketilen Arithmetica'dan Keyflare kazanmaz; bunun yerine, her Uyandırıcının tur başına oynadığı ilk Komut Kartı (Keyflare Yenilenmeleri × 3) + 100 değerinde Keyflare sağlar.\n\nBölünmez Alem: Artık diğer Diyarların Saf Diyar, Çift Diyar Ustalığı veya Çift Hasar Güçlendirmesi efektlerini tetiklemez.\n\nİlksel Yankı: Uyanış Kartları Hazırlan 1 kazanır; her turda ilk kez oynanıldığında, o an donanımlı olan Müfreze otomatik olarak serbest bırakılır.\n\nBellek Parçaları: Müfreze, İlkçağ: İkili Tekerrür ve İlkçağ: Üçlü Vahiy ile değiştirilir ve taşınan Müfrezenin kendisi artık serbest bırakılamaz.\n\n-İlkçağ: İkili Tekerrür: Eldeki Müfrezelerden 3 tanesini Keşfet, ardından 1 tanesini seçerek iki kez serbest bırak.\n-İlkçağ: Üçlü Vahiy: Eldeki Müfrezelerden 3 set Keşfet; her set 3 farklı Müfreze içerir. Bir set seçerek içindeki her Müfrezeyi sırayla bir kez serbest bırak.\nİlkçağ: İkili Tekerrür ve İlkçağ: Üçlü Vahiy'de yer alan Müfrezeler, sekiz tür İlksel Bellek'ten seçilir.\nİlkçağ: İkili Tekerrür ve İlkçağ: Üçlü Vahiy, her biri yalnızca 1 Müfreze serbest bırakma olarak sayılır. Efektleri birden fazla kez tetiklendiğinde, yalnızca ilk geçerli olan Müfreze hesaba katılır.\n\nİlkçağ: Kaos Ustalığı: Diyar Ustalığı, İlkçağ: Kaos Ustalığı olur. Her bir İlkçağ: Kaos Ustalığı puanı, Müfreze Potansiyelini %0,05 artırır. Her bir Müfreze Potansiyeli puanı; Sabit Zehir, Sabit Karşı Atak, Sabit Güç, Sabit Kadim Közler değerlerini %2 artırır; Sabit Kalkan, Sabit HP Yenilenmesi, Sabit Güç Azalması & Dokunaç Hasarı kazanımı, Kritik Oranı, Kritik Hasar, Hasar Güçlendirmesi, Diyar Ustalığı, Aliemus Üretimi, Embriyo Füzyonu ve Keyflare Üretimini %1 artırır."
  },
  AwakerTalent_146937_TalentName_1 = {
    Text = "İlkel Nefes"
  },
