  AwakerTalent_46445_TalentDesc_1 = {
    Text = "Salvador'un Ocak İyileştirmesi, HP Yenilenmesi Artışından fayda sağlar."
  },
  AwakerTalent_46445_TalentName_1 = {
    Text = "Ruhların Çobanı"
  },
  AwakerTalent_46446_TalentDesc_1 = {
    Text = "Ramona ilave 2.5 Keyflare Yenilenme niteliği kazanır. Her Afinite seviyesi, Ramona’ya fazladan 0.5 Keyflare Yenilenme niteliği verir.\nHer bir Keyflare Yenilenme Seviyesi puanı için, \"Kraliçenin Kılıcı\"nın Temel Hasarı %1 artar ve oynandıktan sonra 0.75 Geçici Diyar Ustalığı kazan."
  },
  AwakerTalent_46446_TalentName_1 = {
    Text = "Gümüş Kalp Rezonansı"
  },
  AwakerTalent_46487_TalentDesc_1 = {
    Text = "Ramona: Eskimiş ilave 2,5 Anahtar Parıltısı Yenilenme niteliği kazanır. Her Afinite seviyesi, Ramona: Eskimiş'e ayrıca 0,5 Anahtar Parıltısı Yenilenme niteliği verir.\nHer Anahtar Parıltısı Yenilenme Seviyesi niteliği için, \"Temel Saldırı\"nın döngü etkisi Ramona: Eskimiş'e %0,2 Krit. Oranı, \"Temel Savunma\"nın döngü etkisi ise Ramona: Eskimiş'e 0,2 Aliemus kazandırır."
  },
  AwakerTalent_46487_TalentName_1 = {
    Text = "Gümüş Kalp Rezonansı"
  },
  AwakerTalent_49872_TalentDesc_1 = {
    Text = "Nautila'nın sahip olduğu her 1 Diyar Ustalığı Özelliği için, <color=#FFC800>\"Hazır ve Nazır\"</color>'ın Karşı Saldırı Hasarı %0,25 artar."
  },
  AwakerTalent_49872_TalentName_1 = {
    Text = "Günlük Bakım"
  },
  AwakerTalent_49873_TalentDesc_1 = {
    Text = "Nymphaea’nın sahip olduğu her %1 Hasar Güçlendirmesi niteliği için, \"Ölüm Çanı\" ve \"Benliğin Geçidi\"nin neden olduğu Temel Zehir Etkisi %0,5 artar."
  },
  AwakerTalent_49873_TalentName_1 = {
    Text = "Nüfuz Etme"
  },
  AwakerTalent_51744_TalentDesc_1 = {
    Text = "Savaş başında ele 1 \"Saplantı\" yerleştir.\nMiryam'ın \"Temel Saldırı\"sı %50 Dokunaç Hasarı bonusu alır.\nMiryam ve kuşandığı Kader Çarkı & Ahit tarafından sağlanan her %1 Kritik Hasar için, Taşkınlık'ının GÜÇ Üretimi, Dokunaç Hasarı, Aliemus ve Zehir Uygulama/Tetikleme etkileri %0,2 güçlenir."
  },
  AwakerTalent_51744_TalentName_1 = {
    Text = "Sönmez Bağlılık"
  },
  AwakerTalent_52071_TalentDesc_1 = {
    Text = "Tulu’nun ve kuşandığı WoD & Ahit’in sahip olduğu her Aliemus Dolum Seviyesi puanı için, \"Strike\" +%5 Dokunaç Hasarı ve STR bonusu kazanır. \"Uçurum Buyruğu\" %15 Dokunaç Hasarı ve STR Hasar Artışı alır."
  },
  AwakerTalent_52071_TalentName_1 = {
    Text = "Tanrı Kralın Kudreti"
  },
  AwakerTalent_52086_TalentDesc_1 = {
    Text = "Sanga ve kuşandığı WoD & Ahit’in sahip olduğu her %1 Ölüm Direnci için, \"Basic Strike\" ve \"Basic Defense\"ten kazanılan Aliemus’u 0,03 puan artır; ayrıca \"Yitik Sanat\" fazladan %0,15 Kritik Oranı ve Hasar bonusu kazanır."
  },
  AwakerTalent_52086_TalentName_1 = {
    Text = "Ölümün Aydınlanması"
  },
  AwakerTalent_54047_TalentDesc_1 = {
    Text = "Doll’un sahip olduğu her 1 Aliemus Dolum Seviyesi niteliği için, \"Dış Diyar Cerrahisi\" ve \"Equivalent Borsa\"nın HP Yenilenmesi etkilerini %0,5 artır."
  },
  AwakerTalent_54047_TalentName_1 = {
    Text = "Gnosis Yapısökümü"
  },
  AwakerTalent_54072_TalentDesc_1 = {
    Text = "Ogier'in sahip olduğu her %1 Mühür Hasadı için, \"Yedi sanat ve erdem\"den kazanılan Geçici GÜÇ %3 artar."
  },
  AwakerTalent_54072_TalentName_1 = {
    Text = "Biçimsiz Arındırma"
  },
  AwakerTalent_54073_TalentDesc_1 = {
    Text = "·Alva’nın sahip olduğu her %1 Ölüm Direnci için, Temel Hasar %0,5 artar."
  },
  AwakerTalent_54073_TalentName_1 = {
    Text = "Dinamik Görüş"
  },
