  AwakerTalent_54158_TalentDesc_1 = {
    Text = "Sorel ve onun kuşandığı WoD & Ahit’in sahip olduğu her %1 Kritik Oranı için, \"Temel Savunma\"dan elde edilen Aliemus 0,2 artırılır."
  },
  AwakerTalent_54158_TalentName_1 = {
    Text = "Gösterişin Koruyucusu"
  },
  AwakerTalent_55109_TalentDesc_1 = {
    Text = "Jenkin ve kuşandığı Kader Çarkı ile Ahit’in sağladığı her %1 Kritik Oranı için, \"Basic Strike\" ve \"Get 'em! Brown!\"ın Temel Hasarı %2 artar."
  },
  AwakerTalent_55109_TalentName_1 = {
    Text = "Ortak Düşman"
  },
  AwakerTalent_55176_TalentDesc_1 = {
    Text = "Erica ve kuşandığı Kader Çarkı & Ahit tarafından sağlanan her 1 Anahtar Parıltısı Yenilenme Seviyesi için, \"Elektromanyetik Patlama\" Erica’ya %0,5 Geçici Kritik Oranı ve Krit. Hasar verir."
  },
  AwakerTalent_55176_TalentName_1 = {
    Text = "Harici Güç Kaynağı"
  },
  AwakerTalent_55202_TalentDesc_1 = {
    Text = "Tur başında, 1 yığın Düş Yemi elde et.\n1 yığın Düş Yemi tüketmek, bu savaşta \"Kayıpların Koruyucusu\" ve \"Düşlerin Nekropolisi\"nin Sayacını %5 SLD kadar artırır.\nWanda ve kuşandığı Kader Çarkı & Ahit tarafından sağlanan her 1% Hasar Güçlendirmesi niteliği için, \"Düşlerin Nekropolisi\"nin Sayacı %0,75 artar."
  },
  AwakerTalent_55202_TalentName_1 = {Text = "Vahiy"},
  AwakerTalent_55367_TalentDesc_1 = {
    Text = "Casiah ve kuşandığı Kader Çarkı ile Ahit’in sağladığı her 1 Diyar Ustalığı için, \"Sihir Karnavalı\" Casiah’ın tüm Temel Hasarını %0,2 artırır."
  },
  AwakerTalent_55367_TalentName_1 = {
    Text = "Sihir Ustası"
  },
  AwakerTalent_55507_TalentDesc_1 = {
    Text = "Tinct ve kuşandığı Kader Çarkı ile Ahit’in sağladığı her %1 Mühür Hasadı için, \"Starlight Aurora\" ilave %0,15 Geçici Kritik Oranı kazanır."
  },
  AwakerTalent_55507_TalentName_1 = {
    Text = "Gezegen Gezgini"
  },
  AwakerTalent_55837_TalentDesc_1 = {
    Text = "Horla'nın \"Vuruş\" ve \"Savun\" Komut Kartları Mezmur olarak kabul edilir.\nHorla'nın Komut Kartları Sıçrama Etkilerini tetiklediğinde, o Mezmurla ilişkili duygu hâline girer. Horla aynı anda yalnızca tek bir duygu hâline sahip olabilir ve farklı bir Mezmurun Sıçrama Etkisini tetiklemek, duygu hâlini karşılık gelen duyguya dönüştürür. Her duygu, Horla o duygu hâlindeyken etkin olan, tüm takımı etkileyen pasif bir güçlendirme sağlar. Her duygu hâli, Horla'nın Yüceltme'sinin farklı bir etkisini güçlendirir. Duygu hâli keşif boyunca sürer.\nHorla'nın sahip olduğu her %1 Ölüm Direnci için, Horla'nın mevcut duygu hâlinin pasif etki değeri, Köken değerinin %0,1'i kadar artar."
  },
  AwakerTalent_55837_TalentName_1 = {
    Text = "Duygulu Kalem"
  },
  AwakerTalent_56174_TalentDesc_1 = {
    Text = "Faros, her 1% Hasar Güçlendirmesi niteliği için \"Lemuria’nın Yitik Şehri\" nden fazladan %0,4 Karakter Kalkanı kazanır."
  },
  AwakerTalent_56174_TalentName_1 = {Text = "Ev Hasreti"},
  AwakerTalent_56175_TalentDesc_1 = {
    Text = "Caecus'un sahip olduğu her %1 Mühür Hasadı için, \"Temel Darbe\" %1 Karşı Saldırı bonusu kazanır."
  },
  AwakerTalent_56175_TalentName_1 = {
    Text = "Asi Dikenler"
  },
  AwakerTalent_56223_TalentDesc_1 = {
    Text = "Celeste bir Komut Kartı oynadıktan sonra, düşmana saldırması için 1 Dokunaç tetiklenir. Celeste’in, onun WoD’larının ve Ahit’in sahip olduğu her bir Diyar Ustalığı puanı için, bu etkinleştirme fazladan %0,5 Dokunaç Hasarı verir."
  },
  AwakerTalent_56223_TalentName_1 = {
    Text = "Yolculuk Borusu"
  },
  AwakerTalent_57336_TalentDesc_1 = {
    Text = "Salvador'un sahip olduğu her %1 Mühür Hasadı niteliği için, Kızıl Ocak'ın üst sınırı Maksimum HP'nin %0,15'i kadar artar."
  },
  AwakerTalent_57336_TalentName_1 = {
    Text = "Tüm Yaşamın Kökeni"
  },
  AwakerTalent_57408_TalentDesc_1 = {
    Text = "Agrippa ve kuşandığı WoD & Ahit'in sahip olduğu her %1 Mühür Hasadı için, \"Solgun Lütuf\"un Temel Kalkanı +%0,5 ve Temel Zehri +%1 artar."
  },
  AwakerTalent_57408_TalentName_1 = {
    Text = "Ahit Mührü"
  },
  AwakerTalent_57419_TalentDesc_1 = {
    Text = "Faint'in sahip olduğu her %1 Ölüm Direnci niteliği için, \"Yıldızların Beşiği\" ve \"Göz Kamaştıran Renk\" tarafından sağlanan Karşı Saldırı %0,2 artar ve \"Yıldızların Beşiği\"nin Ölüm Direnci üst sınırı +%2 yükselir."
  },
  AwakerTalent_57419_TalentName_1 = {
    Text = "İkincil Kundak"
  },
  AwakerTalent_57567_TalentDesc_1 = {
    Text = "Helot'un sahip olduğu her %1 Hasar Güçlendirmesi niteliği için, \"Çıkmazda Hayatta Kalma\" bu tur Helot'un verdiği Hasarı %0,3 artırır."
  },
  AwakerTalent_57567_TalentName_1 = {
    Text = "Acı Mührü"
  },
  AwakerTalent_58448_TalentDesc_1 = {
    Text = "Ryker bir düşmanı öldürdüğünde 5 Kara Mühür elde eder. Ryker'ın sahip olduğu her %1 Mühür Hasadı için, elde edilen miktar +%1, keşif başına en fazla 5 kez.\nSavaş yoluyla 75/150/300 Kara Mühür elde ettikten sonra, kalıntı kapasitesi +1 ve savaş sonunda kalıntı listesine eklemek için bir <C05_zaowu:\"Kaotik Miras\"> seç."
  },
  AwakerTalent_58448_TalentName_1 = {
    Text = "Kazanan Hepsini Alır"
  },
  AwakerTalent_70306_TalentDesc_1 = {
    Text = "Reis Savaşlarında, turun başında ve \"Erime·Doll\" Yüceltim saldığında 1 yığın \"Finale\" elde et. \"Finale\" en fazla 10 yığına ulaşabilir ve 10 yığına ulaştığında ele 1 adet \"Yanılsamanın Sonu\" yerleştir."
  },
  AwakerTalent_70306_TalentName_1 = {
    Text = "Yok Oluş Yolu"
  },
  AwakerTalent_74099_TalentDesc_1 = {
    Text = "Bu yetenek yalnızca \"Yıldız Bölümü\" safhalarında etkilidir.\nBu Uyanan'ın DAY, SLD ve DEF değerleri [Arg1]% artar ve ilk Uyanışlarında [Arg2] Keyflare kazanırlar.\nHer bir Dokunaç saldırısı, Geçici Dokunaç Hasarını Tulu'nun SLD'sinin [Arg3]%’i kadar artırır; tur başına en fazla [Arg4] kez birikir.\nTakımda başka 1/2/3 \"Lemuryalı\" Uyanan olduğunda, tüm düşmanlar %10/%25/%50 daha fazla Dokunaç Hasarı alır."
  },
