  AwakerTalent_74101_TalentDesc_1 = {
    Text = "Bu yetenek yalnızca \"Astral Reign\" aşamalarında geçerlidir.\nBu Uyandırıcıların KON, SLD ve SAV +[Arg1]% artar ve ilk Uyanış'larında [Arg2] Keyflare kazanırlar.\nRyker +[Arg3]% Kritik Oranı ve +[Arg4]% Kara Mühür Hasadı kazanır. Savaş boyunca en az 400 Kara Mühür elde edildiyse, bir sonraki savaşın başında 1 \"Kaotik Miras\" yükseltilir."
  },
