  AwakerTalent_74108_TalentDesc_1 = {
    Text = "·Bu yetenek yalnızca \"Yıldız Hükümranlığı\" Sahnelerinde geçerlidir.\n·Bu Uyandırıcı'nın KON, ATK ve SAV değerleri [Arg1]% artar ve bu Uyandırıcı ilk kez Uyanış oynadıktan sonra [Arg2] S-Enerjisi kazanır.\n·Ogier'in verdiği Kalkan [Arg3]% artar, verdiği Güç [Arg4]% artar. Her Taşkınlık kullanımından sonra bu savaşta Ogier'in verdiği Kalkan, SAV'ın 1%'i kadar ek olarak artar."
