  AwakerTalent_74126_TalentDesc_1 = {
    Text = "Bu yetenek yalnızca \"Yıldız Bölümü\" aşamalarında etkilidir.\nBu Uyanan'ın DAY, SLD ve SAV değerleri [Arg1]% artar ve ilk Uyanışlarında [Arg2] Keyflare kazanırlar.\nLeigh'in KUV Üretimi etkisi +[Arg4]%. Leigh'in Komut Kartı oynandıktan sonra, Leigh'in SLD'sinin [Arg3]%’ine eşit KUV kazan. Bu etki, mevcut kaybedilen HP’ye bağlı olarak en fazla %200’e kadar artabilir. Tur başına en fazla 3 kez tetiklenir."
  },
