  AwakerTalent_74127_TalentDesc_1 = {
    Text = "Bu yetenek yalnızca \"Astral Reign\" aşamalarında geçerlidir.\nBu Uyandırıcı'nın KON, SLD ve SAV +[Arg1]% artar ve ilk Uyanış'larında [Arg2] Keyflare kazanırlar.\nEldeki her \"Harika Mutfak\" için, Karen'ın İyileştirme etkisi +[Arg4]% artar, en fazla 3 yığın. Her \"Harika Mutfak\" oynandığında, Karen'ın Zehir etkisi bu savaş boyunca +[Arg3]% artar, en fazla 20 yığın."
  },
