  AwakerTalent_78618_TalentDesc_1 = {
    Text = "Bu Yetenek yalnızca \"Yıldız Bölümü\" safhalarında etkilidir.\nBu Uyanan'ın DAY, SLD ve SAV'ı [Arg1]% artar ve ilk Uyanışlarında [Arg2] Anahtar Alevi kazanırlar.\n \"Izdırapla Kefaret\" in Temel Hasarı, Pollux'un SLD'sinin [Arg3]%'i kadar artar.\nHer 50 \"Günah Damgası\" yığını için, eline 1 adet \"Kutsal Kalp\" ekle.\n \"Günah Damgası\" 100 yığına ulaştığında, \"Kutsal Kalp\"üçüncü oynanışında Tüketildiğinde 1 adet Pollux'un Beceri Kartı çek.\nHasar verirken, \"Günah Damgası\" nın etkisi \"Işık Taşıyıcı Kilisesi\" ne mensup düşmanlara karşı ikiye katlanır."
  },
