  AwakerTalent_78620_TalentDesc_1 = {
    Text = "Bu yetenek yalnızca \"Yıldız Hâkimiyeti\" aşamalarında geçerlidir.\nBu Uyandırıcının KON, SLD ve SAV değerleri +[Arg1]% artar ve ilk Uyanışında [Arg2] S-Enerjisi kazanır.\nSavaşın başında tüm düşmanlar [Arg3]% daha fazla Dokunaç Hasarı alır. Bu etki \"Aequor\" düşmanlarına karşı iki katına çıkar. \"Yıldırım Cezası\"nın \"Aequor\" düşmanlarına verdiği Aktif Hasar +[Arg4]%."
  },
