  AwakerTalent_78622_TalentDesc_1 = {
    Text = "Bu yetenek yalnızca \"Yıldız Bölümü\" sahnelerinde etkilidir.\nBu Uyanan'ın DAY, SLD ve DEF değerleri [Arg1]% artar ve ilk Uyanışlarında [Arg2] Anahtar Alevi kazanırlar.\n\"Fiamma\"nın güçlendirme etkileri +[Arg3]% olur. Her turun başlangıcından sonra ve kart atma aşamasından önce, eldeki kartlardan tüm \"Yanma\"yı temizle. Temizlenen her \"Yanma\" yığını için Kathigu-Ra 1 \"Tutuşma\" yığını kazanır."
