  AwakerTalent_78623_TalentDesc_1 = {
    Text = "Bu yetenek yalnızca \"Yıldız Hâkimiyeti\" aşamalarında geçerlidir.\nBu Uyandırıcının KON, SLD ve SAV değerleri +[Arg1]% artar ve ilk Uyanışında [Arg2] S-Enerjisi kazanır.\nCaraboo'nun Taşkınlık Kritik Oranı ve Kritik Hasarı +[Arg3]%. \"Tokluk\" yığınlarının sağladığı Maksimum can bonusu miktarı +[Arg5]%.\n\"Buz Ovaları\" arazisinde: \"Karlı Büyü\" Arithmetica Maliyeti -1; Hasar isabet sayısı +1; tüm düşmanlara hasar ver ve Semptom: Zayıflık uygula."
  },
