  AwakerTalent_78645_TalentDesc_1 = {
    Text = "Bu Yetenek yalnızca \"Yıldız Bölümü\" safhalarında etkilidir.\nBu Uyanan'ın DAY, SLD ve DEF'i [Arg1]% artar ve ilk Uyanışlarında [Arg2] Keyflare kazanırlar.\nTüm Uyananların kazandığı Güç [Arg3]% artar.\nClementine \"Böceksiler\" düşmanlarına Hasar verdiğinde, verilen Hasarın [Arg4]%’ine eşit bir Kanama etkisi uygular. Her turda ilk kez Clementine bir Karakter Kalkanı sağladığında veya Can yenilediğinde, \"Böceksiler\" düşmanları geçici olarak Clementine'in DEF'inin [Arg5]%’ine eşit Güç kaybeder."
  },
