  AwakerTalent_78911_TalentDesc_1 = {
    Text = "Bu yetenek yalnızca \"Yıldız Bölümü\" safhalarında etkilidir.\nBu Uyanan'ın DAY, SLD ve DEF değerleri [Arg1]% artar ve ilk Uyanışlarında [Arg2] Keyflare kazanırlar.\nMurphy: Sahte Doğumlu Hasar verdiğinde, hedefe verilen Hasarın [Arg3]%’ine eşit \"Kurban\" yükü uygular. \"Yaşam Mührü\" durumunun \"Doğum Ritüeli\" yük artırma etkisi ikiye katlanır.\nTakımda başka 1/2/3 \"Lemuryalı\" Uyanan olduğunda: Maks SY +%6/%15/%30; herhangi bir \"Lemuryalı\" Uyanan Yüceltim kullandıktan sonra, Murphy: Sahte Doğumlu'nun DEF'inin %50/%125/%250'sine eşdeğer Kalkan kazanılır. Tur başına bir kezle sınırlıdır; Kalkan Üretimi Artışından fayda sağlamaz."
  },
