  AwakerTalent_79211_TalentDesc_1 = {
    Text = "Clementine'in Komut Kartı, Hasar verdikten sonra 1 yığın \"Ortak Duyum\" kazanır.\nClementine ve kuşandığı Kader Çarkı & Ahit tarafından sağlanan her 1 Anahtar Alevi Yenilenmesi niteliği, Kritik Oranı ve Krit. Hasarı %0,35 artırır.\nUltra Tur başlangıcında, tüm düşmanların \"Psişik Travma\" ve \"Fobik Takıntı\"sını kaldır. Tüm düşmanlardan kaldırılan her bir \"Psişik Travma\" yığını için 50 Anahtar Alevi kazan; kaldırılan her bir \"Fobik Takıntı\" yığını için diğer Uyananlar 2 Aliemus kazanır."
  },
