  AwakerTalent_89775_TalentDesc_1 = {
    Text = "Her tur ilk kez \"Oniks Tüy\" oynamak, hedefe Castor'un SLD'sinin %840'ı kadar \"Aşınma\" uygular ve 10 Aliemus verir.\nCastor'un sahip olduğu her %1 Hasar Güçlendirmesi için, uygulanan \"Aşınma\" Temel miktarı +%1.\nSavaş sonrasında, bu Keşif boyunca Castor'un uyguladığı \"Aşınma\" kalıcı olarak +%20.\nPatron Savaşları'nda uygulanan \"Aşınma\" iki katına çıkar.\n\"Aşınma\" uyguladıktan sonra, Castor'un Hasar çıkışı bu tur uygulanan \"Aşınma\" miktarının +%5'i kadar artar.\nCastor'un verdiği Hasar \"Aşınma\"yı kaldırmaz."
  },
  AwakerTalent_89775_TalentName_1 = {
    Text = "Kutsal Tüylerle Arınma"
  },
